WITH scored AS (SELECT id, supplier_name, city, LEAD(rating) OVER w_ordered AS next_rating, ROW_NUMBER() OVER w_ordered AS seq_no FROM suppliers WINDOW w_ordered AS (PARTITION BY country ORDER BY rating, id)), metrics AS (SELECT *, AVG(next_rating) OVER w_grp AS next_rating_avg_6, NTILE(5) OVER (PARTITION BY city ORDER BY next_rating DESC, id) AS next_rating_bucket, PERCENT_RANK() OVER (ORDER BY next_rating NULLS FIRST) AS next_rating_percent_rank, SUM(next_rating) OVER (PARTITION BY city) AS city_sum_next_rating, LEAD(seq_no, 1) OVER w_part AS next_seq_no FROM scored WHERE next_rating > 4.0 WINDOW w_grp AS (ORDER BY next_rating, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY city ORDER BY seq_no, id)), base AS (SELECT *, next_rating / NULLIF(next_rating_percent_rank, 0) AS next_rating_per_next_rating_percent_rank, COALESCE(city, 'OTHER') AS resolved_city FROM metrics WHERE city IS NOT NULL AND city_sum_next_rating BETWEEN 10 AND 19), with_last AS (SELECT s.*, latest.product_launch_date, latest.product_price FROM base s LEFT JOIN LATERAL (SELECT c.launch_date AS product_launch_date, c.price AS product_price FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT DATE_TRUNC('WEEK', product_launch_date) AS week_start, PERCENTILE_APPROX(next_rating, ARRAY(0.25, 0.5, 0.75)) AS next_rating_quartiles, COUNT(CASE WHEN city = 'Singapore' THEN 1 END) AS singapore_count FROM with_last GROUP BY 1;
